import related from "@/data/related.json";
import type { Garment } from "@/types/garment";

/**
 * Related garments precomputed by the hfa-ml re-ranker (nDCG@5 0.93 vs 0.70 for the
 * weighted score in relatedGarments.ts, on a 50-query blind-judged benchmark).
 *
 * data/related.json is regenerated by `python -m hfa.export_related` in the hfa-ml repo.
 * It only covers photographed garments; anything else falls back to the weighted score.
 */
interface RelatedFile {
  generated: string;
  k: number;
  related: Record<string, string[]>;
}

const data = related as RelatedFile;

/** Accession numbers the re-ranker recommends for this one, best first; [] if it has none. */
export function getPrecomputedRelatedAccessions(accession?: string): string[] {
  if (!accession) return [];
  return data.related[accession] ?? [];
}

/**
 * Resolve the re-ranker's recommendations to garments that are actually loaded,
 * best first, skipping excluded ids, up to `limit`.
 */
export function getPrecomputedRelated(
  garment: Garment,
  allGarments: Garment[],
  limit: number,
  excludeIds: Set<string> = new Set()
): Garment[] {
  const accessions = getPrecomputedRelatedAccessions(garment.accessionNumber);
  if (accessions.length === 0 || limit <= 0) return [];

  const byAccession = new Map<string, Garment>();
  for (const g of allGarments) {
    if (g.accessionNumber) byAccession.set(g.accessionNumber, g);
  }

  const out: Garment[] = [];
  for (const acc of accessions) {
    const g = byAccession.get(acc);
    if (g && g.id !== garment.id && !excludeIds.has(g.id)) out.push(g);
    if (out.length >= limit) break;
  }
  return out;
}
